class Product {
  Product({required this.id,required this.name,this.slug='',this.description='',this.brand='',this.price=0,this.salePrice,this.currency='YER',this.stock=0,this.image,this.gallery=const[],this.vendorName='',this.vendorId,this.categories=const[],this.variants=const[],this.rating=0,this.reviewsCount=0,this.soldCount=0});
  final int id; final String name; final String slug; final String description; final String brand; final num price; final num? salePrice; final String currency; final num stock; final String? image; final List<String> gallery; final String vendorName; final int? vendorId; final List<String> categories; final List<Map<String,dynamic>> variants; final num rating; final num reviewsCount; final num soldCount;
  factory Product.fromJson(Map<String,dynamic> j){final gallery=<String>[];final rawGallery=j['gallery']??j['images'];if(rawGallery is List){for(final g in rawGallery){if(g is String)gallery.add(g);else if(g is Map&&g['url']!=null)gallery.add(g['url'].toString());}}final cats=<String>[];final rc=j['categories'];if(rc is List){for(final c in rc){if(c is Map&&c['name']!=null)cats.add(c['name'].toString());else if(c is String)cats.add(c);}}final vars=<Map<String,dynamic>>[];if(j['variants'] is List)vars.addAll((j['variants'] as List).whereType<Map>().map((e)=>Map<String,dynamic>.from(e)));return Product(id:int.tryParse('${j['id']??0}')??0,name:'${j['name']??''}',slug:'${j['slug']??''}',description:'${j['description']??''}',brand:'${j['brand']??''}',price:num.tryParse('${j['price']??j['effective_price']??0}')??0,salePrice:j['sale_price']==null?null:num.tryParse('${j['sale_price']}'),currency:'${j['currency']??'YER'}',stock:num.tryParse('${j['available_stock']??j['stock']??0}')??0,image:j['main_image_url']??j['main_image']??j['image'],gallery:gallery,vendorName:'${(j['vendor'] is Map?(j['vendor'] as Map)['store_name']:j['vendor_name'])??''}',vendorId:j['vendor'] is Map?int.tryParse('${(j['vendor'] as Map)['id']??''}'):int.tryParse('${j['vendor_id']??''}'),categories:cats,variants:vars,rating:num.tryParse('${j['rating']??0}')??0,reviewsCount:num.tryParse('${j['reviews_count']??0}')??0,soldCount:num.tryParse('${j['sold_count']??0}')??0);}
}
